from pathlib import Path
root=Path('outputs/ROMDex')
def patch(file,old,new):
 p=root/file;s=p.read_text(encoding='utf-8')
 if new in s:return
 assert old in s,(file,old[:80])
 p.write_text(s.replace(old,new,1),encoding='utf-8',newline='\n')
