patch('content/workspace-runtime.js',"function conditionalPoint(p){return", "function conditionIndex(){return globalThis.romdexConditions?.indexFor(data,town())||null}\nfunction conditionRecord(p){return p.contentRecordId||p.elementId}\nfunction conditionTurns(p){const index=conditionIndex();if(!index||!p?.legacyData?.conditionModel)return null;const c=globalThis.romdexConditions;return pages(p).map(entry=>{const speaker=resolveSpeaker(p,entry,null),effects=c.blockEffects(index,conditionRecord(p),p.id,entry.blockId);return {speakerKey:speaker.key,speakerLabel:speaker.label,entries:[{...entry,speakerLabel:speaker.label,system:speaker.system}],conditionIds:[...new Set(effects.flatMap(e=>e.conditionIds))],access:effects.length?effects.map(e=>c.describe(e.requires)).join(' OR '):'Unresolved source reference; gameplay access is not confirmed.',unresolved:!effects.length||effects.some(e=>c.hasUnknown(e.requires))};})}\nfunction visibleTurns(p){const turns=speakerTurns(p);return !conditionIndex()||stage==='conditional'?turns:turns.filter(t=>stage==='unresolved'?t.unresolved:t.conditionIds?.includes(stage))}\nfunction conditionalPoint(p){return")
