patch('content/workspace-runtime.js',"$('conditional').disabled=!additional.length;", "$('conditional').disabled=conditionIndex()?false:!additional.length;\n if(conditionIndex()){$('conditional').textContent='All Content ('+records.length+')';let button=$('unresolved-conditions');if(!button){button=document.createElement('button');button.id='unresolved-conditions';$('conditional').after(button);button.onclick=()=>{flushNote();stage='unresolved';pointId=null;pageIndex=0;renderDialogue();renderTimeline()};}button.textContent='Unresolved ('+records.filter(r=>r.turn.unresolved).length+')';button.setAttribute('aria-pressed',String(stage==='unresolved'));}else $('unresolved-conditions')?.remove();")
