patch('content/workspace-runtime.js','function setTestStatus(p,turn,value,checked)',"function renderConditionInspector(p,turn){if(!conditionIndex())return;const pane=document.querySelector('.conditions-pane');if(pane){const condition=pane.querySelector('.condition');if(condition){condition.replaceChildren();const strong=document.createElement('strong');strong.textContent='Access Requirements';condition.append(strong,document.createTextNode(turn?.access||'No dialogue alternative in this filter.'));}const eyebrow=pane.querySelector('.eyebrow');if(eyebrow)eyebrow.textContent=stage==='conditional'?'All Content':stage==='unresolved'?'Unresolved Checks':'Condition '+stageLabel(stage);}const label=$('speaker-label');if(label)label.parentElement.title='Dialogue alternatives are inspected separately; this is not a simulated conversation order.';}\nfunction setTestStatus(p,turn,value,checked)")
